{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Pentosan polysulfate, a highly sulfated polysaccharide, has oral bioavailability of only 0.5-1% in healthy subjects, supporting very low oral absorption for sulfated carbohydrate structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Acarbose, a carbohydrate-based drug, has negligible absolute oral bioavailability of <2% in humans, supporting low systemic absorption for polar saccharides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Glycyrrhizin, a glucuronic acid-containing glycoside, has an oral bioavailability of approximately 0.25% in humans, supporting low F for carboxylated sugar-containing molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Dextran sulfate has poor oral bioavailability in humans, supporting the pattern that sulfated carbohydrate polymers are poorly absorbed orally.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query molecule is a sulfated, carboxylated disaccharide with multiple polar groups and negative charges. Direct analogues such as pentosan polysulfate, dextran sulfate, acarbose, and glycyrrhizin consistently show very low oral bioavailability (<2-4%), far below the 20% threshold, so the query is predicted to have low oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability record exists for the exact query molecule.",
    "Extrapolation relies on related sulfated/carbohydrate-containing molecules rather than the identical disaccharide.",
    "Possible transporter-mediated uptake or prodrug behavior specific to this exact structure is not captured by the available analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

